/* ---------------- French. One language is one file like this; src/lang.js explains how it is used. ----------------
   words: a whole English line, or one part of a line between " · ", with its French.
   rules: the same for lines with a number or a name in them. The first rule that fits wins; a rule that answers null is passed over.
   help:  the Help page's answers, by topic id (src/helpdata.js has the English). A button named in **bold** keeps its English name
          when its screen is still in English, so it can be found.
   Covered so far: the sidebar, Today, the welcome, Find anything, Help, and the feedback page in a returned paper. */
const FR_NUM = { no: 0, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10, eleven: 11, twelve: 12 };
const frN = w => { const k = String(w).toLowerCase(); return k in FR_NUM ? FR_NUM[k] : +w; };
const frP = (n, one, many) => n + ' ' + (n > 1 ? many : one);
const frLast = s => s === 'the last set of papers' ? 'le dernier lot de copies' : s;
// The line under Today's date: what she teaches, then what is waiting.
function frHomeSay(k) {
  const m = /^(?:(No classes today\.|(\w+) class(?:es)? today\.) ?)?(.*)$/.exec(k); if (!m) return null;
  let teach = '', work = '';
  if (m[1]) teach = m[2] ? frP(frN(m[2]), 'cours', 'cours') + ' aujourd’hui.' : 'Pas de cours aujourd’hui.';
  const w = m[3];
  let x;
  if (!w) work = '';
  else if ((x = /^(\w+) sets? of papers to mark, (\w+) ready to hand back\.$/i.exec(w))) work = frP(frN(x[1]), 'lot de copies', 'lots de copies') + ' à corriger, ' + frN(x[2]) + (frN(x[2]) > 1 ? ' prêts' : ' prêt') + ' à rendre.';
  else if ((x = /^(\w+) sets? of papers to mark\.$/i.exec(w))) work = frP(frN(x[1]), 'lot de copies', 'lots de copies') + ' à corriger.';
  else if ((x = /^(\w+) sets? of papers ready to hand back\.$/i.exec(w))) work = frP(frN(x[1]), 'lot de copies prêt', 'lots de copies prêts') + ' à rendre.';
  else if (/^nothing waiting to be marked\.$/i.test(w)) work = 'Rien à corriger.';
  else return null;
  if (!teach && !work) return null;
  return (teach + (work ? ' ' + work : '')).trim();
}
